/// <summary>
/// Class used when exporting pages to configuration file
/// </summary>
public class TFMPagesExport
{
    Set referencedFilters;
}

Method.Source:
    public XmlElement GetConfigurationXmlForPages()
    {
        XmlDocument				xmlDoc;
        XmlElement              xmlPagesElement;
        TFMPages                pages = TFMPagesProvider::getAllPages();
        MapEnumerator           pagesEnum = pages.getPages().getEnumerator();
        TFMPagesMapHelper		pagesMapHelper = new TFMPagesMapHelper();
        TFMPage					page;
		xmlDoc = new XmlDocument();

        xmlPagesElement = xmlDoc.createElement('pages');
        xmlPagesElement.setAttribute('tweak','append');
        pagesMapHelper.init();
        while(pagesEnum.moveNext())
        {
            page = pagesEnum.currentValue();
            if (page.parmAlwaysIncludeInOutput() || pagesMapHelper.pagesReferenced().exists(page.parmId()))
            {
                referencedFilters.add(page.parmFilter());
                this.addTFMPageXmlToPagesElement(page, xmlPagesElement, false, pages);
            }
        }

        return xmlPagesElement;
    }

/// <summary>
/// Constructor for class
/// </summary>
/// <returns>A TFMPagesExport instance</returns>
public static TFMPagesExport Construct()
{
    return new TFMPagesExport();
}

/// <summary>
/// Constructor for class
/// </summary>
private void new()
{
    referencedFilters = new Set(Types::String);
}

private void addTFMPageXmlToPagesElement(TFMPage _mobPage, XmlElement _pagesElement, boolean _replace, TFMPages _pages)
{
    XmlNodeList pagesNodeList;
    XmlDocument xmlDocPagePages = new XmlDocument();
    XMLNodeListIterator xmlListIterator;

    xmlDocPagePages = _mobPage.getXML(_pages);
    if(xmlDocPagePages)
    {
        pagesNodeList = xmlDocPagePages.SelectNodes('//*[local-name()="page"]');;
        xmlListIterator = new XMLNodeListIterator(pagesNodeList);

        while(xmlListIterator.moreValues())
        {
            XmlNode node = xmlListIterator.value();
            XmlElement nodeElement = node as XmlElement;
            if(_replace)
            {
                nodeElement.setAttribute('tweak', 'replace');
            }
            _pagesElement.appendChild(_pagesElement.ownerDocument().importNode(node, true));

            xmlListIterator.nextValue();
        }
    }
}
